#ifndef RPNCE_CORE_UNITS_H
#define RPNCE_CORE_UNITS_H

/* Unit conversions. A stack value can carry a unit; pressing another unit
 * of the same dimension converts it. The tables are generated by
 * tools/genunits.py from exact definitions. */

#include <stdint.h>
#include <ti/real.h>
#include "units_count.h"

typedef struct {
    const char *label;      /* as in the menu, with symbol codes */
    uint8_t dim;            /* DIM_* */
    const char *factor;     /* one unit in the dimension's base unit */
    const char *offset;     /* temperatures: base = (value + offset) * factor */
    uint8_t reciprocal;     /* fuel: base = factor / value (mpg) */
} unit_t;

extern const unit_t unit_table[UNIT_COUNT];
extern const uint8_t unit_base[DIM_COUNT];

/* Converts a value between units of the same dimension. Call under the
 * error handler (dividing by a zero mpg, for example, raises an error). */
real_t unit_convert(const real_t *value, uint8_t from, uint8_t to);

#endif
